export function calcularDistancia(lat1,lng1,lat2,lng2){return Math.sqrt(Math.pow(lat1-lat2,2)+Math.pow(lng1-lng2,2))}export function razonesPorLugarId(lugaresConRazones){var mapa={};(lugaresConRazones||[]).forEach(function(x){if(x.lugar&&x.lugar.id!=null&&x.razones&&x.razones.length){mapa[x.lugar.id]=x.razones[0]}});return mapa}export function hayCambioEnLista(listaAnterior,listaActual){if(!listaAnterior||!listaActual)return true;if(listaAnterior.length!==listaActual.length)return true;var hashAnterior=listaAnterior.map(function(l){return l.id}).join(",");var hashActual=listaActual.map(function(l){return l.id}).join(",");return hashAnterior!==hashActual}